def sort_names_by_surname_then_given(names):
    def key(name):
        first, last = name.split(' ', 1)
        return (last, first)
    return sorted(names, key=key)

def sort_by_product_of_digits(nums):
    def digit_product(n):
        product = 1
        for d in str(n):
            product *= int(d)
        return product
    return sorted(nums, key=lambda n: (digit_product(n), n))

def top_k_and_rest_sorted(nums, k):
    s = sorted(nums)
    n = len(s)
    rest = s[:n - k]
    top = list(reversed(s[n - k:]))
    return (top, rest)

def rank_students_dense_dict(records):
    scores = sorted({score for _, score in records}, reverse=True)
    rank_map = {score: i + 1 for i, score in enumerate(scores)}
    return {name: rank_map[score] for name, score in records}

def check_intervals_sorted_no_overlap(intervals):
    for i in range(len(intervals) - 1):
        s1, e1 = intervals[i]
        s2, e2 = intervals[i + 1]
        if not (s1 <= s2):
            return False
        if e1 > s2:
            return False
    return True

def is_sorted_rotation_of_sorted(nums):
    n = len(nums)
    if n <= 1:
        return True
    breaks = 0
    for i in range(n):
        if nums[i] > nums[(i + 1) % n]:
            breaks += 1
    return breaks <= 1

def sort_by_frequency_desc_then_first_occurrence(nums):
    from collections import Counter
    counts = Counter(nums)
    first_occurrence = {}
    for i, n in enumerate(nums):
        if n not in first_occurrence:
            first_occurrence[n] = i
    distinct = list(first_occurrence.keys())
    return sorted(distinct, key=lambda x: (-counts[x], first_occurrence[x]))

def kth_smallest_using_merge(a, b, k):
    merged = sorted(a + b)
    return merged[k - 1]

def sort_by_string_length_then_reverse_alpha(words):
    step1 = sorted(words, reverse=True)
    return sorted(step1, key=len)

def group_and_sort_by_key(records):
    result = {}
    for cat, val in records:
        result.setdefault(cat, []).append(val)
    for cat in result:
        result[cat].sort()
    return result
